package testrec

import (
	"bytes"
	"embed"
	"encoding/json"
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"unicode"
)

//go:embed golib/*.txt
var golib embed.FS

// GoModule is the module name of the generated Go tests (go.mod at the tests folder's root).
const GoModule = "termwright-tests"

// genHeader starts every Go file Termwright writes; files without a "Code generated by Termwright"
// first line (// or #) are never overwritten.
const genHeader = "// Code generated by Termwright"

func generated(b []byte) bool {
	return bytes.HasPrefix(b, []byte(genHeader)) || bytes.HasPrefix(b, []byte("# Code generated by Termwright"))
}

// GoLibFiles are the helper files of the generated Go tests, by path in the tests folder.
func GoLibFiles() map[string][]byte {
	rd := func(n string) []byte { b, _ := golib.ReadFile("golib/" + n); return b }
	return map[string][]byte{"go.mod": rd("go.mod.txt"), "lib/twtest/twtest.go": rd("twtest.go.txt"), "lib/junit/main.go": rd("junit.go.txt"),
		"lib/python/twtest.py": rd("twtest.py.txt"), "lib/python/run_tests.py": rd("run_tests.py.txt"),
		"lib/tcl/twtest.tcl": rd("twtest.tcl.txt"), "lib/tcl/run_tests.tcl": rd("run_tests.tcl.txt")}
}

// GoFile is the generated Go test file of a case file: cases/vlan/add.yaml → cases/vlan/add_test.go.
func GoFile(caseFile string) string {
	return strings.TrimSuffix(caseFile, filepath.Ext(caseFile)) + "_test.go"
}

// GenerateGo writes a case as a Go test (package from its folder, TestXxx from its file name) that
// uses lib/twtest; each step is a subtest.
func GenerateGo(c Case, caseFile string) ([]byte, error) {
	caseFile = filepath.ToSlash(caseFile)
	dir := filepath.ToSlash(filepath.Dir(caseFile))
	var b bytes.Buffer
	q := strconv.Quote
	fmt.Fprintf(&b, "%s from %s. DO NOT EDIT - change the YAML (or record it again) and save it.\n\n", genHeader, caseFile)
	fmt.Fprintf(&b, "package %s\n\nimport (\n\t\"testing\"\n\n\t%q\n)\n\n", goPkg(dir), GoModule+"/lib/twtest")
	name := c.Name
	if name == "" {
		name = strings.TrimSuffix(filepath.Base(caseFile), filepath.Ext(caseFile))
	}
	fmt.Fprintf(&b, "// %s", oneLine(name))
	if c.Description != "" {
		fmt.Fprintf(&b, ": %s", oneLine(c.Description))
	}
	fmt.Fprintf(&b, "\nfunc Test%s(t *testing.T) {\n", goIdent(strings.TrimSuffix(filepath.Base(caseFile), filepath.Ext(caseFile))))
	if len(c.Params) > 0 {
		var ps []string
		for _, p := range c.Params {
			ps = append(ps, goMap(p))
		}
		fmt.Fprintf(&b, "\ttwtest.Params(t, %s, []map[string]string{\n%s,\n}, func(tw *twtest.T) {\n", goMap(c.Vars), strings.Join(ps, ",\n"))
	} else {
		fmt.Fprintf(&b, "\ttw := twtest.New(t, %s)\n", goMap(c.Vars))
	}
	if len(c.Restore) > 0 {
		var ks, ss []string
		for _, k := range c.Restore {
			ks = append(ks, q(k))
		}
		for _, x := range Sessions(c, nil) {
			ss = append(ss, q(x))
		}
		fmt.Fprintf(&b, "\ttw.Restore([]string{%s}, %s)\n", strings.Join(ks, ", "), strings.Join(ss, ", "))
	}
	for _, ps := range phased(c) {
		goStep(&b, ps.st, ps.i, ps.phase, q(PhaseLabel(ps.phase)+stepName(ps.st, ps.i)), "\t", 0)
	}
	if len(c.Restore) > 0 {
		b.WriteString("\ttw.Finish()\n")
	}
	if len(c.Params) > 0 {
		b.WriteString("\t})\n")
	}
	b.WriteString("}\n")
	out, err := format.Source(b.Bytes())
	if err != nil {
		return b.Bytes(), fmt.Errorf("generated Go does not parse: %w", err)
	}
	return out, nil
}

func goExpect(e Expect) string {
	q := strconv.Quote
	switch {
	case e.Table != nil:
		t := e.Table
		if t.Rows != nil {
			return fmt.Sprintf("a.RowCount(%s).Equals(%q)", goMap(t.Where), strconv.Itoa(*t.Rows))
		}
		if t.Column == "" {
			if t.Exists != nil && !*t.Exists {
				return fmt.Sprintf("a.RowCount(%s).Equals(\"0\")", goMap(t.Where))
			}
			return fmt.Sprintf("a.RowCount(%s).Greater(0)", goMap(t.Where))
		}
		v := fmt.Sprintf("a.Cell(%s, %s)", goMap(t.Where), q(t.Column))
		if t.Matches != "" {
			return v + ".Matches(" + goStr(t.Matches) + ")"
		}
		return v + goChain(Expect{Equals: t.Equals, NotEquals: t.NotEquals, Greater: t.Greater, Less: t.Less, Exists: t.Exists})
	case e.Contains != "":
		return "a.Contains(" + q(e.Contains) + ")"
	case e.NotContains != "":
		return "a.NotContains(" + q(e.NotContains) + ")"
	case e.Matches != "":
		return "a.Matches(" + goStr(e.Matches) + ")"
	case e.Status != 0:
		return fmt.Sprintf("a.StatusIs(%d)", e.Status)
	case e.Schema != "":
		return "// the JSON Schema check runs in Termwright only"
	case e.MaxMs != 0 && e.Field == "" && e.JSON == "" && e.OID == "":
		return fmt.Sprintf("a.MaxMs(%d)", e.MaxMs)
	case e.Field != "" || e.JSON != "" || e.OID != "":
		v := "a.JSON(" + q(e.JSON) + ")"
		if e.OID != "" {
			v = "a.OID(" + q(e.OID) + ")"
		} else if e.Field != "" {
			v = "a.Field(" + goStr(e.Field) + ")"
		}
		return v + goChain(e)
	}
	return "// empty check"
}

// goStr quotes s, as a raw string when it has backslashes (regular expressions read better).
func goStr(s string) string {
	if strings.Contains(s, `\`) && !strings.ContainsAny(s, "`\n\r") {
		return "`" + s + "`"
	}
	return strconv.Quote(s)
}

func goMap(m map[string]string) string {
	if len(m) == 0 {
		return "nil"
	}
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	var p []string
	for _, k := range keys {
		p = append(p, strconv.Quote(k)+": "+strconv.Quote(m[k]))
	}
	return "map[string]string{" + strings.Join(p, ", ") + "}"
}

func oneLine(s string) string { return strings.Join(strings.Fields(s), " ") }

// goIdent makes CamelCase from a file name: "vlan-42_up" → "Vlan42Up".
func goIdent(s string) string {
	var b strings.Builder
	up := true
	for _, r := range s {
		if !unicode.IsLetter(r) && !unicode.IsDigit(r) || r > unicode.MaxASCII {
			up = true
			continue
		}
		if up {
			r = unicode.ToUpper(r)
			up = false
		}
		b.WriteRune(r)
	}
	if b.Len() == 0 {
		return "Case"
	}
	return b.String()
}

// goPkg is a package name for a folder: cases/vlan-tests → vlantests.
func goPkg(dir string) string {
	base := strings.ToLower(filepath.Base(dir))
	var b strings.Builder
	for _, r := range base {
		if r < unicode.MaxASCII && (unicode.IsLetter(r) || unicode.IsDigit(r)) {
			b.WriteRune(r)
		}
	}
	p := b.String()
	if p == "" || unicode.IsDigit(rune(p[0])) || p == "main" {
		p = "cases" + p
	}
	return p
}

// WriteGo writes the case's Go test next to it and the helper files (go.mod, lib/) when they are
// missing or were written by Termwright. It returns the Go file, relative to the folder.
func (f Folder) WriteGo(caseFile string) (string, error) {
	c, err := f.Load(caseFile)
	if err != nil {
		return "", err
	}
	if c, err = f.Prepare(c); err != nil { // procedures inlined, data rows as params
		return "", err
	}
	p, _ := f.find(caseFile)
	rel, _ := filepath.Rel(f.Root, p)
	rel = filepath.ToSlash(rel)
	src, err := GenerateGo(c, rel)
	if err != nil {
		return "", err
	}
	if err := f.WriteGoLib(); err != nil {
		return "", err
	}
	out := GoFile(rel)
	if err := f.writeGenerated(out, src); err != nil {
		return out, err
	}
	py, err := GeneratePython(c, rel)
	if err != nil {
		return out, err
	}
	if err := f.writeGenerated(PyFile(rel), py); err != nil {
		return out, err
	}
	tcl, err := GenerateTcl(c, rel)
	if err != nil {
		return out, err
	}
	return out, f.writeGenerated(TclFile(rel), tcl)
}

// WriteGoLib writes go.mod and lib/ (only files Termwright made are replaced).
func (f Folder) WriteGoLib() error {
	for rel, b := range GoLibFiles() {
		if err := f.writeGenerated(rel, b); err != nil {
			return err
		}
	}
	return nil
}

// writeGenerated writes rel unless a file without Termwright's header is there (the person's own).
func (f Folder) writeGenerated(rel string, b []byte) error {
	p, err := f.path(rel)
	if err != nil {
		return err
	}
	if old, err := os.ReadFile(p); err == nil {
		if bytes.Equal(old, b) {
			return nil
		}
		if !generated(old) && rel != "go.mod" {
			return nil // the person's own file
		}
		if rel == "go.mod" {
			return nil // kept: it may list the person's own modules
		}
	}
	if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
		return err
	}
	return os.WriteFile(p, b, 0o644)
}

// goChain: the Value checks of e (.Equals(…) …; none: .IsFound()).
func goChain(e Expect) string {
	q := strconv.Quote
	var c []string
	if e.Exists != nil {
		c = append(c, fmt.Sprintf(".Exists(%v)", *e.Exists))
	}
	if e.Equals != nil {
		c = append(c, ".Equals("+q(*e.Equals)+")")
	}
	if e.NotEquals != nil {
		c = append(c, ".NotEquals("+q(*e.NotEquals)+")")
	}
	if e.Greater != nil {
		c = append(c, ".Greater("+strconv.FormatFloat(*e.Greater, 'g', -1, 64)+")")
	}
	if e.Less != nil {
		c = append(c, ".Less("+strconv.FormatFloat(*e.Less, 'g', -1, 64)+")")
	}
	if len(c) == 0 {
		c = append(c, ".IsFound()")
	}
	return strings.Join(c, "")
}

// goStep writes one step: tw.Step (or tw.Cleanup) with its action and checks; a loop becomes a Go loop
// over its values with its steps inside. name is a Go expression.
func goStep(b *bytes.Buffer, st Step, i int, phase, name, ind string, depth int) {
	q := strconv.Quote
	if st.Loop != nil {
		x := fmt.Sprintf("x%d", depth)
		var vals string
		switch {
		case len(st.Loop.Values) > 0:
			var l []string
			for _, v := range st.Loop.Values {
				l = append(l, q(v))
			}
			vals = "tw.List(" + strings.Join(l, ", ") + ")"
		case st.Loop.Range != "" && !strings.Contains(st.Loop.Range, "{{"):
			r, _ := rangeValues(st.Loop.Range)
			var l []string
			for _, v := range r {
				l = append(l, q(v))
			}
			vals = "[]string{" + strings.Join(l, ", ") + "}"
		default:
			src := st.Loop.From
			if src == "" {
				src = st.Loop.Range
			}
			vals = "tw.Values(" + q(src) + ")"
		}
		if st.If != "" {
			fmt.Fprintf(b, "%sif tw.Cond(%s) {\n", ind, q(st.If))
		}
		fmt.Fprintf(b, "%sfor _, %s := range %s {\n%s\ttw.Set(%s, %s)\n", ind, x, vals, ind, q(st.Loop.Var), x)
		for j, in := range st.Loop.Steps {
			goStep(b, in, j, phase, q(PhaseLabel(phase)+stepName(in, j))+" + \" ["+st.Loop.Var+"=\" + "+x+" + \"]\"", ind+"\t", depth+1)
		}
		fmt.Fprintf(b, "%s}\n", ind)
		if st.If != "" {
			fmt.Fprintf(b, "%s}\n", ind)
		}
		return
	}
	if phase == "cleanup" {
		fmt.Fprintf(b, "%stw.Cleanup(%s, func(s *twtest.Step) {\n", ind, name)
	} else {
		fmt.Fprintf(b, "%stw.Step(%s, %v, func(s *twtest.Step) {\n", ind, name, st.ContinueOnFail && phase == "")
	}
	var w bytes.Buffer
	if st.Manual != nil {
		fmt.Fprintf(b, "%s\ts.Skip(%s)\n%s})\n", ind, q("manual step - runs in Termwright, where a person answers it: "+st.Manual.Instruction), ind)
		return
	}
	if st.If != "" {
		fmt.Fprintf(&w, "\t\tif !s.Cond(%s) {\n\t\t\ts.Skip(%s)\n\t\t}\n", q(st.If), q("if "+st.If+" is false"))
	}
	if st.Wait > 0 {
		fmt.Fprintf(&w, "\t\ts.Wait(%s)\n", strconv.FormatFloat(st.Wait, 'g', -1, 64))
	}
	if st.Retry != nil {
		ej, _ := json.Marshal(st.Expect)
		fmt.Fprintf(&w, "\t\ts.RetryUntil(%s, %s, %s)\n", strconv.FormatFloat(orF(st.Retry.Timeout, 60), 'g', -1, 64), strconv.FormatFloat(orF(st.Retry.Interval, 5), 'g', -1, 64), q(string(ej)))
	}
	if actions(st) > 0 {
		goAction(&w, st)
	}
	for _, l := range strings.SplitAfter(w.String(), "\n") {
		if l != "" {
			b.WriteString(ind + strings.TrimPrefix(l, "\t"))
		}
	}
	fmt.Fprintf(b, "%s})\n", ind)
}

func orF(x, d float64) float64 {
	if x <= 0 {
		return d
	}
	return x
}

// goAction writes a step's action, checks and saves (indented two tabs).
func goAction(b *bytes.Buffer, st Step) {
	q := strconv.Quote
	if raw, ok := rawStep(st); ok {
		fmt.Fprintf(b, "\t\ta := s.Raw(%s)\n\t\t_ = a\n", goStr(raw))
		return
	}
	switch {
	case st.Run != nil:
		if st.Run.Parse != "" {
			fmt.Fprintf(b, "\t\ta := s.RunParsed(%s, %s, %s, %s, %d)\n", q(st.Run.Session), q(st.Run.Command), q(st.Run.Prompt), q(st.Run.Parse), st.Timeout)
		} else {
			fmt.Fprintf(b, "\t\ta := s.Run(%s, %s, %s, %d)\n", q(st.Run.Session), q(st.Run.Command), q(st.Run.Prompt), st.Timeout)
		}
	case st.HTTP != nil:
		h := st.HTTP
		var f []string
		add := func(k, v string) {
			if v != "" {
				f = append(f, k+": "+q(v))
			}
		}
		add("Session", h.Session)
		add("Environment", h.Environment)
		add("Collection", h.Collection)
		m := strings.ToUpper(h.Method)
		if m == "" {
			m = "GET"
		}
		add("Method", m)
		add("URL", h.URL)
		add("Body", h.Body)
		if len(h.Headers) > 0 {
			f = append(f, "Headers: "+goMap(h.Headers))
		}
		if st.Timeout > 0 {
			f = append(f, "Timeout: "+strconv.Itoa(st.Timeout))
		}
		fmt.Fprintf(b, "\t\ta := s.HTTP(twtest.Request{%s})\n", strings.Join(f, ", "))
	case st.Upgrade != nil:
		fmt.Fprintf(b, "\t\ta := s.Upgrade(%s, %s, %d)\n", q(st.Upgrade.Session), q(st.Upgrade.Image), st.Timeout)
	case st.Traffic != nil:
		fmt.Fprintf(b, "\t\ta := s.Traffic(%s, %d)\n", q(st.Traffic.Test), st.Timeout)
	case st.SNMP != nil:
		sn := st.SNMP
		op := strings.ToLower(sn.Op)
		if op == "" {
			op = "get"
		}
		f := []string{"Session: " + q(sn.Session), "Op: " + q(op)}
		if len(sn.OIDs) > 0 {
			var o []string
			for _, x := range sn.OIDs {
				o = append(o, q(x))
			}
			f = append(f, "OIDs: []string{"+strings.Join(o, ", ")+"}")
		}
		if len(sn.Values) > 0 {
			var o []string
			for _, x := range sn.Values {
				o = append(o, fmt.Sprintf("{OID: %s, Type: %s, Value: %s}", q(x.OID), q(x.Type), q(x.Value)))
			}
			f = append(f, "Values: []twtest.SetValue{"+strings.Join(o, ", ")+"}")
		}
		if st.Timeout > 0 {
			f = append(f, "Timeout: "+strconv.Itoa(st.Timeout))
		}
		fmt.Fprintf(b, "\t\ta := s.SNMP(twtest.SNMP{%s})\n", strings.Join(f, ", "))
	}
	for _, e := range st.Expect {
		fmt.Fprintf(b, "\t\t%s\n", goExpect(e))
	}
	for _, s := range st.Save {
		if s.OID != "" {
			fmt.Fprintf(b, "\t\ta.OID(%s).Save(%s)\n", q(s.OID), q(s.Var))
		} else if s.Column != "" {
			fmt.Fprintf(b, "\t\ta.Cell(%s, %s).Save(%s)\n", goMap(s.Where), q(s.Column), q(s.Var))
		} else if s.Field != "" {
			fmt.Fprintf(b, "\t\ta.Field(%s).Save(%s)\n", goStr(s.Field), q(s.Var))
		} else if s.JSON != "" {
			fmt.Fprintf(b, "\t\ta.JSON(%s).Save(%s)\n", q(s.JSON), q(s.Var))
		}
	}
	if len(st.Expect) == 0 && len(st.Save) == 0 {
		b.WriteString("\t\t_ = a\n")
	}
}
